<?php
require __DIR__.'/bootstrap.php';
$sent=false;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        verify_csrf();
        $name=trim((string)($_POST['name']??''));
        $email=trim((string)($_POST['email']??''));
        $message=trim((string)($_POST['message']??''));
        if($name===''||$message===''||!filter_var($email,FILTER_VALIDATE_EMAIL)) throw new RuntimeException('Preencha nome, e-mail válido e mensagem.');
        $ipHash=hash('sha256',(string)($_SERVER['REMOTE_ADDR']??'').'|'.date('Y-m-d'));
        $q=$pdo->prepare('INSERT INTO contact_leads(id,name,email,phone,church_name,members_count,plan,message,status,source,ip_hash) VALUES(?,?,?,?,?,?,?,?,"new","pricing",?)');
        $q->execute([app_uuid(),$name,$email,null_if_blank($_POST['phone']??null),null_if_blank($_POST['church_name']??null),null_if_blank($_POST['members_count']??null),null_if_blank($_POST['plan']??null),$message,$ipHash]);
        $sent=true;
    }catch(Throwable $e){$error=$e->getMessage();}
}
$plans=[
 ['name'=>'Básico','price'=>'R$ 97','desc'=>'Ideal para igrejas pequenas que estão começando','popular'=>false,'items'=>['Bot WhatsApp básico','Até 200 membros','PIX automático','Pedidos de oração','1 congregação','Relatórios básicos','Suporte por e-mail']],
 ['name'=>'Pro','price'=>'R$ 197','desc'=>'Para igrejas em crescimento que precisam de mais recursos','popular'=>true,'items'=>['Bot WhatsApp avançado','Até 1.000 membros','PIX automático','Pedidos de oração com IA','Até 5 congregações','Eventos ilimitados','Documentos personalizados','Relatórios completos','Suporte por WhatsApp']],
 ['name'=>'Enterprise','price'=>'R$ 397','desc'=>'Solução completa para ministérios e denominações','popular'=>false,'items'=>['Bot WhatsApp ampliado','Membros ilimitados','Congregações ilimitadas','IA e automações avançadas','Eventos ilimitados','Documentos personalizados','API de integração','Relatórios avançados','Suporte prioritário']],
];
