ption><option>Pro</option><option>Enterprise</option></select></div><div class="field full"><label>Mensagem *</label><textarea class="textarea" name="message" required><?=e($_POST['message']??'Quero conhecer melhor o Igreja Master e receber informações para implantação.')?></textarea></div></div><button class="btn btn-primary" style="width:100%;margin-top:16px">Enviar interesse</button></form></div></section>
